import{_ as l,a0 as p,w as o,s as d,I as n,x as a,a1 as t,A as i,ao as c}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"在雲端自動化設置和交付虛擬機 | LCTT x X-CMD","titleTemplate":false,"description":"在雲端自動化設置和交付虛擬機 | LCTT (202204) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在雲端自動化設置和交付虛擬機 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在雲端自動化設置和交付虛擬機 | LCTT (202204) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202204/20210126 Automate setup and delivery for virtual machines in the cloud","title":"在雲端自動化設置和交付虛擬機","tag":"202204","desc":""},"relativePath":"202204/20210126 Automate setup and delivery for virtual machines in the cloud.md","filePath":"[post].md"}'),r={name:"202204/20210126 Automate setup and delivery for virtual machines in the cloud.md"};function u(h,s,g,k,b,f){const e=p("Link");return o(),d("div",null,[s[20]||(s[20]=n("h1",{id:"在雲端自動化設置和交付虛擬機",tabindex:"-1"},[a("在雲端自動化設置和交付虛擬機 "),n("a",{class:"header-anchor",href:"#在雲端自動化設置和交付虛擬機","aria-label":"Permalink to “在雲端自動化設置和交付虛擬機”"},"​")],-1)),s[21]||(s[21]=n("blockquote",null,[n("p",null,"通過使用 Testcloud 自動化設置過程並交付一個準備運行的虛擬機，在幾分鐘之內準備好一個雲鏡像。")],-1)),s[22]||(s[22]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202204/30/130336l2l1a77p7m8hwp28.jpg",alt:""})],-1)),n("p",null,[s[2]||(s[2]=a("如果你是一個在雲端使用 Fedora ",-1)),t(e,{href:"https://en.wikipedia.org/wiki/Qcow"},{default:i(()=>[...s[0]||(s[0]=[a("qcow2 鏡像",-1)])]),_:1}),s[3]||(s[3]=a(" 的開發者或者愛好者，在一個鏡像準備使用之前，你總是不得不做一大堆初始化設置。我對此深有體會，所以我很想找到一種使設置過程更加簡單的方法。碰巧，整個 Fedora 質量保證團隊也有同感，所以我們開發了 ",-1)),t(e,{href:"https://pagure.io/testcloud"},{default:i(()=>[...s[1]||(s[1]=[a("Testcloud",-1)])]),_:1}),s[4]||(s[4]=a(" 。",-1))]),s[23]||(s[23]=c(`<p>Testcloud 是一個可以輕鬆的在幾分鐘之內準備雲鏡像測試的工具。它用幾個命令就可以在雲端自動化設置並交付準備運行的虛擬機（VM）。</p><p>Testcloud：</p><ol><li>下載 qcow2 鏡像</li><li>用你選擇的名稱創建實例</li><li>創建一個密碼為 <code>passw0rd</code>，用户名為 <code>fedora</code> 的用户</li><li>分配一個 IP 地址，以便於你之後用 SSH 登錄到雲端</li><li>啓動、停止、刪除和列出一個實例</li></ol><h3 id="安裝-testcloud" tabindex="-1">安裝 Testcloud <a class="header-anchor" href="#安裝-testcloud" aria-label="Permalink to “安裝 Testcloud”">​</a></h3><p>要開始你的旅程，首先你必須安裝 Testcloud 軟件包。你可以通過終端或者“軟件”應用來安裝它。在這兩種情況下，軟件包的名字都是 <code>testcloud</code> 。用以下命令安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install testcloud -y</span></span></code></pre></div><p>一旦安裝完成，將你所需要的用户添加到 <code>testcloud</code> 用户組，這有助於 Testcloud 自動完成設置過程的剩餘部分。執行這兩個命令，添加你的用户到 <code>testcloud</code> 用户組，並通過提升組權限重啓會話：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo usermod -a -G testcloud $USER</span></span>
<span class="line"><span>$ su - $USER</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/adduser.png" alt="添加用户到 testcloud 組" title="Add user to testcloud group"></p><h3 id="像老手一樣玩轉雲鏡像" tabindex="-1">像老手一樣玩轉雲鏡像 <a class="header-anchor" href="#像老手一樣玩轉雲鏡像" aria-label="Permalink to “像老手一樣玩轉雲鏡像”">​</a></h3><p>一旦你的用户獲得了所需的組權限，創建一個實例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ testcloud instance create &lt;instance name&gt; -u &lt;url for qcow2 image&gt;</span></span></code></pre></div><p>或者，你可以使用 <code>fedora:latest/fedora:XX</code>（<code>XX</code> 是你的 Fedora 發行版本）來代替 完整的 URL 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ testcloud instance create &lt;instance name&gt; -u fedora:latest</span></span></code></pre></div><p>這將返回你的虛擬機的 IP 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ testcloud instance create testcloud272593 -u https://download.fedoraproject.org/pub/fedora/linux/releases/33/Cloud/x86_64/images/Fedora-Cloud-Base-33-1.2.x86_64.qcow2  </span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>INFO:Successfully booted instance testcloud272593</span></span>
<span class="line"><span>The IP of vm testcloud272593:  192.168.122.202</span></span>
<span class="line"><span>------------------------------------------------------------</span></span>
<span class="line"><span>To connect to the VM, use the following command (password is &#39;passw0rd&#39;):</span></span>
<span class="line"><span>ssh fedora@192.168.122.202</span></span></code></pre></div><p>你可以用默認用户 <code>fedora</code> 登錄，密碼是 <code>passw0rd</code>（注意是零）。你可以使用 <code>ssh</code>、<code>virt-manager</code> 或者支持連接到 libvirt 虛擬機方式來連接到它。</p><p>另一種創建 Fedora 雲的方式是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ testcloud instance create testcloud193 -u fedora:33</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>WARNING:Not proceeding with backingstore cleanup because there are some testcloud instances running.</span></span>
<span class="line"><span>You can fix this by following command(s):</span></span>
<span class="line"><span>testcloud instance stop testcloud272593</span></span>
<span class="line"><span></span></span>
<span class="line"><span>DEBUG:Local downloads will be stored in /var/lib/testcloud/backingstores.</span></span>
<span class="line"><span>DEBUG:successfully changed SELinux context for image /var/lib/testcloud/backingstores/Fedora-Cloud-Base-33-1.2.x86_64.qcow2</span></span>
<span class="line"><span>DEBUG:Creating instance directories</span></span>
<span class="line"><span>DEBUG:creating seed image /var/lib/testcloud/instances/testcloud193/testcloud193-seed.img</span></span>
<span class="line"><span>INFO:Seed image generated successfully</span></span>
<span class="line"><span>INFO:Successfully booted instance testcloud193</span></span>
<span class="line"><span>The IP of vm testcloud193:  192.168.122.225</span></span>
<span class="line"><span>------------------------------------------------------------</span></span>
<span class="line"><span>To connect to the VM, use the following command (password is &#39;passw0rd&#39;):</span></span>
<span class="line"><span>ssh fedora@192.168.122.225</span></span>
<span class="line"><span>------------------------------------------------------------</span></span></code></pre></div><h3 id="玩轉實例" tabindex="-1">玩轉實例 <a class="header-anchor" href="#玩轉實例" aria-label="Permalink to “玩轉實例”">​</a></h3><p>Testcloud 可以用來管理實例。這包括像列出鏡像或者停止和啓動一個實例等活動。</p><p>要列出實例，使用 <code>list</code> 子命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ testcloud instance list                </span></span>
<span class="line"><span>Name                            IP                      State    </span></span>
<span class="line"><span>------------------------------------------------------------</span></span>
<span class="line"><span>testcloud272593                 192.168.122.202         running    </span></span>
<span class="line"><span>testcloud193                    192.168.122.225         running    </span></span>
<span class="line"><span>testcloud252793                 192.168.122.146         shutoff    </span></span>
<span class="line"><span>testcloud93                     192.168.122.152         shutoff</span></span></code></pre></div><p>要停止一個運行的實例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ testcloud instance stop testcloud193  </span></span>
<span class="line"><span>DEBUG:stop instance: testcloud193</span></span>
<span class="line"><span>DEBUG:stopping instance testcloud193.</span></span></code></pre></div><p>要刪除一個實例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ testcloud instance destroy testcloud193  </span></span>
<span class="line"><span>DEBUG:remove instance: testcloud193</span></span>
<span class="line"><span>DEBUG:removing instance testcloud193 from libvirt.</span></span>
<span class="line"><span>DEBUG:Unregistering instance from libvirt.</span></span>
<span class="line"><span>DEBUG:removing instance /var/lib/testcloud/instances/testcloud193 from disk</span></span></code></pre></div><p>要重啓一個運行中的實例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ testcloud instance reboot testcloud93                                                                                        </span></span>
<span class="line"><span>DEBUG:stop instance: testcloud93</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>INFO:Successfully booted instance testcloud93</span></span>
<span class="line"><span>The IP of vm testcloud93:  192.168.122.152</span></span>
<span class="line"><span>usage: testcloud [-h] {instance,image} ...</span></span></code></pre></div><p>嘗試一下 Testcloud ，在評論中讓我知道你的想法。</p><hr>`,31)),n("p",null,[s[6]||(s[6]=a("via: ",-1)),t(e,{href:"https://opensource.com/article/21/1/testcloud-virtual-machines"},{default:i(()=>[...s[5]||(s[5]=[a("https://opensource.com/article/21/1/testcloud-virtual-machines",-1)])]),_:1})]),n("p",null,[s[11]||(s[11]=a("作者：",-1)),t(e,{href:"https://opensource.com/users/sumantro"},{default:i(()=>[...s[7]||(s[7]=[a("Sumantro Mukherjee",-1)])]),_:1}),s[12]||(s[12]=a(" 選題：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[8]||(s[8]=[a("lujun9972",-1)])]),_:1}),s[13]||(s[13]=a(" 譯者：",-1)),t(e,{href:"https://github.com/hwlife"},{default:i(()=>[...s[9]||(s[9]=[a("hwlife",-1)])]),_:1}),s[14]||(s[14]=a(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[10]||(s[10]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[17]||(s[17]=a("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[15]||(s[15]=[a("LCTT",-1)])]),_:1}),s[18]||(s[18]=a(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:i(()=>[...s[16]||(s[16]=[a("Linux中國",-1)])]),_:1}),s[19]||(s[19]=a(" 榮譽推出",-1))])])}const C=l(r,[["render",u]]);export{y as __pageData,C as default};
